theorem dyadicTreeFrontier_antichain (n : ℕ) {s t : DyadicTreeNode}
    (hs : s ∈ dyadicTreeFrontier n) (ht : t ∈ dyadicTreeFrontier n) (hne : s ≠ t) :
    ¬ s.IsPrefix t
